// ============================================================
//  Slide 15 (display) / index 14 — المفاضلة الخوارزمية
//  ومسوغات اختيار الذكاء السربي والجيني
//
//  Visual redesign: three expressive vignettes (DNA / Swarm /
//  Explosion) + four simple justifications taken from the thesis,
//  closing with the dual-algorithm decision + constraint repair.
// ============================================================

import React from "react";
import { motion, useReducedMotion } from "framer-motion";
import {
  Binary,
  Compass,
  Network,
  Zap,
  GitMerge,
  type LucideIcon,
} from "lucide-react";
import { SlideStage, SlideTitleBlock } from "../design/SlideStage";
import { palette, alpha, space, type as typeTokens, radius, shadow } from "../design/tokens";
import { fadeUp, staggerParent, t } from "../design/motion";
import { useStepReveal } from "../../hooks/useStepReveal";
import { StepIndicator } from "../ui/RevealItem";
import { AlgoSceneCard } from "../ui/visualPatterns/AlgoJustificationScene";

interface Props {
  onOpenModal?: (id: string) => void;
}

const reasons: { ar: string; icon: LucideIcon }[] = [
  {
    icon: Network,
    ar: "فضاء حلول هائل الأبعاد: الاختيار التوافقي من بين 79,268 موقعاً مرشحاً يُفضي إلى تعقيد تركيبي أسي (2^N)",
  },
  {
    icon: Binary,
    ar: "معضلة تحسين غير خطية مصنفة ضمن فئة NP-Hard؛ تستحيل معالجتها بالطرق الرياضية الدقيقة في زمن عملي",
  },
  {
    icon: Compass,
    ar: "تعارض متعدد الأهداف (Multi-Objective): موازنة دقيقة بين التغطية الراديوية والتكلفة وكفاءة الطاقة والعدالة",
  },
  {
    icon: Zap,
    ar: "الموازنة الحرجة بين سرعة التقارب ومتانة الحلول وتفادي الاستقرار في القمم المحلية تحت قيود راديوية صارمة",
  },
];

export const Slide13Algorithms: React.FC<Props> = ({ onOpenModal }) => {
  // Steps: 1 title → 2 AGA → 3 BPSO → 4 MILP → 5 reasons → 6 decision
  const { step, totalSteps, goToStep, goNext } = useStepReveal({
    totalSteps: 6,
    initialStep: 1,
    anyKeyAdvance: true,
  });
  const shouldReduce = useReducedMotion();

  const handleClick = (e: React.MouseEvent) => {
    const target = e.target as HTMLElement;
    if (target.closest("button") || target.closest("[data-no-advance]")) return;
    goNext();
  };

  return (
    <div
      onClick={handleClick}
      style={{ width: "100%", height: "100%", cursor: "pointer" }}
      title="انقر أو اضغط أي زر لمتابعة العرض خطوة بخطوة"
    >
      <SlideStage
        variant="default"
        chapter=""
        sectionTag=""
        padding="tight"
      >
        {/* Header row */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "flex-start",
            gap: space.md,
            marginBottom: space.sm,
          }}
        >
          <div style={{ flex: 1, minWidth: 0 }}>
            <SlideTitleBlock
              titleAr="المفاضلة الخوارزمية ومسوغات اعتماد أساليب التحسين الفوق-استدلالية"
              accent="primary"
              compact
            />
          </div>
          <div data-no-advance="true" style={{ paddingTop: 4, flexShrink: 0 }}>
            <StepIndicator
              totalSteps={totalSteps}
              currentStep={step}
              onStepClick={goToStep}
            />
          </div>
        </div>

        {/* Three visual algorithm cards */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 1fr 1fr",
            gap: space.md,
            flex: "1 1 auto",
            minHeight: 0,
          }}
        >
          <AlgoSceneCard
            kind="aga"
            active={step >= 2}
            titleAr="الخوارزمية الجينية التكيفية"
            titleEn="Adaptive Genetic Algorithm"
            origin="نمذجة تطورية بيولوجية: توليد حلول متتالية عبر آليات الانتخاب، العبور التبادلي، والطفرات التكيفية."
            strength="استكشاف واسع لفضاء الحلول (Global Exploration) وتفادي الاستقرار المبكر في الحلول المحلية"
            limit="معدل تقارب زمني أبطأ نسبياً مع تضخم فضاء البحث الطوبولوجي"
            onDetail={onOpenModal ? () => onOpenModal("aga") : undefined}
            detailLabel="تفاصيل AGA ↗"
          />
          <AlgoSceneCard
            kind="bpso"
            active={step >= 3}
            titleAr="تحسين سرب الجسيمات الثنائية"
            titleEn="Binary Particle Swarm Optimization"
            origin="نمذجة السلوك الاجتماعي التكيفي للأسراب: توجيه الجسيمات بالاعتماد على الخبرة الفردية والجمعية (gBest)."
            strength="سرعة تقارب فائقة وتوظيف كفء للذاكرة الجمعية في قرارات الاختيار الثنائي (Binary Selection)"
            limit="حساسية أعلى للاستقرار في حلول محلية عند غياب آليات تصحيح القيود"
            onDetail={onOpenModal ? () => onOpenModal("bpso") : undefined}
            detailLabel="تفاصيل BPSO ↗"
          />
          <AlgoSceneCard
            kind="milp"
            active={step >= 4}
            titleAr="البرمجة الخطية الصحيحة المختلطة"
            titleEn="Mixed-Integer Linear Programming"
            origin="توفر الأمثلية الرياضية القطعية نظرياً، بيد أنها غير قابلة للتطبيق العملي في المعضلات واسعة النطاق."
            strength="ضمان بلوغ الحل الأمثل المطلق رياضياً في النماذج النظرية محدودة الحجم"
            limit="استحالة حاسوبية قطعية أمام حجم شبكة الأطروحة (79,268 موقعاً) نتيجة الانفجار التركيبي الأسي"
          />
        </div>

        {/* Justifications + decision */}
        <div
          style={{
            marginTop: space.md,
            display: "grid",
            gridTemplateColumns: "1.55fr 1fr",
            gap: space.md,
            flexShrink: 0,
          }}
        >
          {/* 4 reasons */}
          <motion.div
            initial={false}
            animate={{
              opacity: step >= 5 ? 1 : 0.12,
              y: step >= 5 ? 0 : 10,
            }}
            transition={t.cinema}
            style={{
              background: "#fff",
              borderRadius: radius.lg,
              border: `2px solid ${alpha(palette.primary, 0.28)}`,
              padding: `${space.md}px ${space.lg}px`,
              boxShadow: shadow.soft,
            }}
          >
            <div
              style={{
                fontSize: typeTokens.small,
                fontWeight: 900,
                color: palette.primary,
                marginBottom: space.sm,
                letterSpacing: "-0.2px",
              }}
            >
              المسوغات المنهجية لاعتماد خوارزميات التحسين الذكية
            </div>
            <motion.div
              variants={staggerParent(0.06, 0)}
              initial={shouldReduce || step < 5 ? undefined : "hidden"}
              animate={step >= 5 ? "visible" : undefined}
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: 8,
              }}
            >
              {reasons.map((r, i) => {
                const Icon = r.icon;
                return (
                  <motion.div
                    key={i}
                    variants={fadeUp}
                    style={{
                      display: "flex",
                      alignItems: "flex-start",
                      gap: 8,
                      background: alpha(palette.primary, 0.06),
                      borderRadius: radius.md,
                      padding: "8px 10px",
                      border: `1px solid ${alpha(palette.primary, 0.12)}`,
                    }}
                  >
                    <span
                      style={{
                        width: 28,
                        height: 28,
                        borderRadius: 8,
                        background: alpha(palette.primary, 0.12),
                        color: palette.primary,
                        display: "inline-flex",
                        alignItems: "center",
                        justifyContent: "center",
                        flexShrink: 0,
                      }}
                    >
                      <Icon size={15} />
                    </span>
                    <span
                      style={{
                        fontSize: 19,
                        fontWeight: 800,
                        color: palette.ink,
                        lineHeight: 1.4,
                      }}
                    >
                      {r.ar}
                    </span>
                  </motion.div>
                );
              })}
            </motion.div>
          </motion.div>

          {/* Thesis decision */}
          <motion.div
            initial={false}
            animate={{
              opacity: step >= 6 ? 1 : 0.1,
              scale: step >= 6 ? 1 : 0.96,
            }}
            transition={t.cinema}
            style={{
              background: `linear-gradient(145deg, ${palette.accentDeep} 0%, ${palette.accent} 55%, ${palette.primaryDeep} 100%)`,
              borderRadius: radius.lg,
              padding: `${space.lg}px ${space.lg}px`,
              color: "#fff",
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              gap: space.sm,
              boxShadow: `0 12px 28px ${alpha(palette.accent, 0.35)}`,
              position: "relative",
              overflow: "hidden",
            }}
          >
            <div
              style={{
                position: "absolute",
                insetInlineEnd: -20,
                bottom: -24,
                width: 110,
                height: 110,
                borderRadius: "50%",
                background: alpha("#fff", 0.06),
                pointerEvents: "none",
              }}
            />
            <div
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 8,
                fontSize: 19,
                fontWeight: 800,
                opacity: 0.9,
              }}
            >
              <GitMerge size={16} />
              المنهجية المقارنة المعتمدة في الأطروحة
            </div>
            <div
              style={{
                fontSize: typeTokens.body,
                fontWeight: 900,
                lineHeight: 1.45,
              }}
            >
              تطبيق مقارن متوازي لخوارزميتي{" "}
              <span style={{ color: "#f5e6a8" }}>BPSO</span>
              {" و "}
              <span style={{ color: "#f5e6a8" }}>AGA</span>
              ، معززتين بآلية{" "}
              <span style={{ color: "#f5e6a8" }}>إصلاح القيود الراديوية</span>
              ، والتحقق العملي على الشبكة الوطنية.
            </div>
            <div
              style={{
                fontSize: typeTokens.micro,
                fontWeight: 700,
                opacity: 0.82,
                lineHeight: 1.4,
              }}
            >
              الغاية الهندسية: التحقق الإحصائي من سرعة التقارب، استقرار الحلول، ومتانة تجاوز القمم المحلية.
            </div>
          </motion.div>
        </div>
      </SlideStage>
    </div>
  );
};

export default Slide13Algorithms;
