function QMark({
  tone,
  active,
  code,
  size = 68,
}: {
  tone: string;
  active: boolean;
  code?: string;
  size?: number;
}) {
  return (
    <div
      style={{
        position: "relative",
        width: size,
        height: size,
        flexShrink: 0,
      }}
    >
      <motion.div
        initial={false}
        animate={{
          scale: active ? 1 : 0.88,
          background: active ? tone : "rgba(255,255,255,0.72)",
          color: active ? "#ffffff" : tone,
          boxShadow: active ? `0 10px 22px ${tone}40` : "none",
        }}
        transition={{ duration: 0.4, ease: EASE }}
        style={{
          width: size,
          height: size,
          borderRadius: "50%",
          border: `3px solid ${tone}`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: size * 0.56,
          fontWeight: 900,
          fontFamily: "Cairo, sans-serif",
          lineHeight: 1,
        }}
      >
        ؟
      </motion.div>
      {code && (
        <span
          style={{
            position: "absolute",
            left: "50%",
            bottom: -7,
            transform: "translateX(-50%)",
            background: tone,
            color: "#ffffff",
            fontSize: 12,
            fontFamily: "Inter, Cairo, sans-serif",
            fontWeight: 800,
            letterSpacing: "0.04em",
            padding: "1px 7px",
            borderRadius: 999,
            lineHeight: 1.3,
          }}
        >
          {code}
        </span>
      )}
    </div>
  );
}

